function normalizarTexto(texto) {
    return texto.replace(/\s+/g, " ").trim();
}


/*
   Elementos que pueden llevar formato dentro de un párrafo
   (por ejemplo <code> o <strong>) y aun así se traducen completos.
   Las referencias (<li> con <a>) quedan fuera a propósito.
*/
const ETIQUETAS_EN_LINEA = ["CODE", "STRONG", "EM", "BR"];

function esTraducible(elemento) {
    return Array.from(elemento.children).every(hijo =>
        ETIQUETAS_EN_LINEA.includes(hijo.tagName)
    );
}


function cambiarIdioma(idioma) {

    document.documentElement.lang = idioma;


    /*
       TRADUCIR TEXTOS
    */

    document.querySelectorAll("body *").forEach(elemento => {

        // No tocar elementos que contienen otros elementos
        // (salvo texto con <code>, <strong> o <em>)
        if (!esTraducible(elemento))
            return;

        const conFormato = elemento.children.length !== 0;

        const textoActual = normalizarTexto(
            conFormato ? elemento.innerHTML : elemento.textContent
        );


        // Guardar texto original solamente una vez
        if (!elemento.dataset.textoOriginal) {
            elemento.dataset.textoOriginal = textoActual;
        }


        const textoOriginal = elemento.dataset.textoOriginal;


        if (idioma === "en") {

            /*
               La traducción puede venir del HTML (atributo data-en)
               o del diccionario. Si existe data-en, tiene prioridad.
            */
            const traduccion =
                elemento.dataset.en
                || traduccionesMTC[textoOriginal];

            if (traduccion) {

                if (conFormato) {
                    elemento.innerHTML = traduccion;
                } else {
                    elemento.textContent = traduccion;
                }

            }

        } else {

            if (conFormato) {
                elemento.innerHTML =
                    textoOriginal;
            } else {
                elemento.textContent =
                    textoOriginal;
            }

        }

    });


    /*
       TRADUCIR ALT DE IMÁGENES
    */

    document.querySelectorAll("img[alt]").forEach(img => {

        if (!img.dataset.altOriginal) {

            img.dataset.altOriginal = img.alt;

        }


        if (idioma === "en") {

            img.alt =
                traduccionesAtributos[img.dataset.altOriginal]
                || img.dataset.altOriginal;

        } else {

            img.alt =
                img.dataset.altOriginal;

        }

    });


    /*
       ACTUALIZAR BOTONES ES / EN
    */

    document.querySelectorAll(".selector-idioma button").forEach(boton => {

        const activo =
            boton.dataset.idioma === idioma;

        boton.classList.toggle(
            "idioma-activo",
            activo
        );

        boton.setAttribute(
            "aria-pressed",
            String(activo)
        );

    });


    /*
       GUARDAR IDIOMA
    */

    try {

        localStorage.setItem(
            "idiomaMTC",
            idioma
        );

    } catch (error) {}

}


/*
   INICIAR
*/

document.addEventListener("DOMContentLoaded", () => {


    /*
       USAR EL SELECTOR QUE YA EXISTE
    */

    const selector =
        document.querySelector(".selector-idioma");


    if (selector) {

        selector
            .querySelectorAll("button[data-idioma]")
            .forEach(boton => {

                boton.addEventListener(
                    "click",
                    () => {

                        cambiarIdioma(
                            boton.dataset.idioma
                        );

                    }
                );

            });

    }


    /*
       RECUPERAR IDIOMA GUARDADO
    */

    let idioma = "es";


    try {

        idioma =
            localStorage.getItem("idiomaMTC")
            || "es";

    } catch (error) {}


    if (idioma !== "es" && idioma !== "en") {

        idioma = "es";

    }


    cambiarIdioma(idioma);

});